// Domain Layer (Inner Hexagon)
class Order {
  constructor(id, customerId, items, totalAmount) {
    this.id = id;
    this.customerId = customerId;
    this.items = items;
    this.totalAmount = totalAmount;
    this.status = 'pending';
    this.createdAt = new Date();
  }

  validate() {
    const errors = [];
    if (!this.customerId) errors.push('customerId is required');
    if (!this.items || this.items.length === 0) errors.push('items are required');
    if (this.totalAmount <= 0) errors.push('totalAmount must be positive');
    return errors;
  }

  confirm() {
    this.status = 'confirmed';
    return { type: 'OrderConfirmed', orderId: this.id };
  }

  toJSON() {
    return {
      id: this.id,
      customerId: this.customerId,
      items: this.items,
      totalAmount: this.totalAmount,
      status: this.status,
      createdAt: this.createdAt
    };
  }
}

// Repository Port (Interface)
class OrderRepository {
  async findById(id) { throw new Error('Not implemented'); }
  async findAll(query) { throw new Error('Not implemented'); }
  async save(order) { throw new Error('Not implemented'); }
  async update(id, order) { throw new Error('Not implemented'); }
}

// Application Layer (Use Case)
class CreateOrderUseCase {
  constructor(orderRepository, eventBus) {
    this.repository = orderRepository;
    this.eventBus = eventBus;
  }

  async execute(command) {
    const order = new Order(
      command.id,
      command.customerId,
      command.items,
      command.totalAmount
    );

    const errors = order.validate();
    if (errors.length > 0) {
      return { success: false, errors };
    }

    await this.repository.save(order);
    await this.eventBus.publish(order.confirm());

    return { success: true, order: order.toJSON() };
  }
}

// Infrastructure Layer (Adapter)
class OrderDatabaseAdapter extends OrderRepository {
  constructor(database) {
    super();
    this.db = database;
    this.collection = 'orders';
  }

  async findById(id) {
    const data = await this.db.collection(this.collection).findOne({ id });
    return data ? new Order(data.id, data.customerId, data.items, data.totalAmount) : null;
  }

  async findAll(query = {}) {
    const data = await this.db.collection(this.collection).find(query).toArray();
    return data.map(d => new Order(d.id, d.customerId, d.items, d.totalAmount));
  }

  async save(order) {
    await this.db.collection(this.collection).insertOne(order.toJSON());
    return order;
  }
}

class OrderHttpAdapter {
  constructor(useCases) {
    this.useCases = useCases;
  }

  async handleCreate(req, res) {
    const result = await this.useCases.create.execute(req.body);
    if (result.success) {
      res.status(201).json(result.order);
    } else {
      res.status(400).json({ errors: result.errors });
    }
  }
}

// Usage
const db = { collection: () => ({ findOne: async () => null, find: () => ({ toArray: async () => [] }), insertOne: async () => {} }) };
const repository = new OrderDatabaseAdapter(db);
const createUseCase = new CreateOrderUseCase(repository, { publish: async () => {} });

